fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 0.5) {
        val text = String.format("%.1f", seconds)
        (if (text.endsWith(".0")) text.dropLast(2) else text) + "s"
    } else {
        "1/${(1.0 / seconds).roundToInt()}s"
    }
}

