import sys

def strip_comments(text):
    out = []
    i = 0
    n = len(text)
    in_line = False
    in_block = False
    in_str = False
    in_chr = False
    while i < n:
        c = text[i]
        nxt = text[i + 1] if i + 1 < n else ''
        if in_line:
            if c == '\n':
                in_line = False
                out.append(c)
        elif in_block:
            if c == '*' and nxt == '/':
                in_block = False
                i += 2
                continue
            if c == '\n':
                out.append(c)
        elif in_str:
            out.append(c)
            if c == '\\' and nxt:
                out.append(nxt)
                i += 2
                continue
            if c == '"':
                in_str = False
        elif in_chr:
            out.append(c)
            if c == '\\' and nxt:
                out.append(nxt)
                i += 2
                continue
            if c == "'":
                in_chr = False
        else:
            if c == '/' and nxt == '/':
                in_line = True
                i += 2
                continue
            if c == '/' and nxt == '*':
                in_block = True
                i += 2
                continue
            if c == '"':
                in_str = True
            elif c == "'":
                in_chr = True
            out.append(c)
        i += 1
    return ''.join(out)

orig_lines = open(sys.argv[1], encoding='utf-8').read().split('\n')
stripped_full = strip_comments('\n'.join(orig_lines))
stripped_lines = stripped_full.split('\n')

result = []
for orig, stripped in zip(orig_lines, stripped_lines):
    s = stripped.rstrip()
    if s == '' and orig.strip() != '':
        continue  # line was only a comment
    result.append(s)
    # drop trailing blank lines if original had none
open(sys.argv[1], 'w', encoding='utf-8').write('\n'.join(result))

