def _update_rights(move, rights, piece):
    if not rights or rights == '-':
        return rights
    src_rank, src_file = int(move[1]) - 1, ord(move[0]) - ord('a')
    dst_rank, dst_file = int(move[3]) - 1, ord(move[2]) - ord('a')
    rights = list(rights)
    if piece in ('K', 'k'):
        for letter in ('KQ' if piece == 'K' else 'kq'):
            if letter in rights:
                rights.remove(letter)
    for corner, letter in _RIGHT_FOR_CORNER.items():
        if (src_rank, src_file) == corner or (dst_rank, dst_file) == corner:
            if letter in rights:
                rights.remove(letter)
    return ''.join(rights) or '-'


